import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"開發手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/index.md","filePath":"zh-TW/dev-guide/index.md","lastUpdated":1785993908000}'),s={name:"zh-TW/dev-guide/index.md"};function i(n,e,l,d,c,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="開發手冊" tabindex="-1">開發手冊 <a class="header-anchor" href="#開發手冊" aria-label="Permalink to &quot;開發手冊&quot;">​</a></h1><p>Lertaro 提供了一套開放的外掛 SDK(<code>Lertaro.PluginSdk</code>)，第三方組件可以參照它來擴充搜尋行為、新增右鍵選單動作、與其他視窗整合，以及自訂介面。本手冊記錄了這套 SDK 的全部內容。</p><ul><li><strong><a href="./architecture.html">架構設計</a></strong> —— App、背景 Service 與外掛之間是如何配合的。</li><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 搭建一個外掛專案並載入它。</li><li><strong>外掛 SDK 參考</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">核心搜尋與動作</a></strong> —— 貢獻搜尋結果與結果動作。</li><li><strong><a href="./sdk/system-adapters.html">系統與對話方塊轉接</a></strong> —— 與檔案總管、原生檔案對話方塊及其他前景視窗整合。</li><li><strong><a href="./sdk/ui-extensions.html">介面與預覽擴充</a></strong> —— 側欄篩選器、結果欄、檔案預覽、縮圖、佈景主題與語言包。</li><li><strong><a href="./sdk/abstractions.html">共用抽象契約</a></strong> —— 外掛收到的唯讀模型(<code>ISearchResult</code>、 <code>IPluginSearchWindow</code>)以及設定結構(<code>IConfigurable</code>)。</li><li><strong><a href="./sdk/services.html">宿主服務</a></strong> —— 宿主公開給外掛的靜態服務(圖示、我的最愛、歷史記錄、檔案中繼資料、目錄索引、外掛專屬設定、記錄)。</li></ul></li><li><strong><a href="./examples.html">外掛範例</a></strong> —— 兩個真實隨附外掛的案例分析。</li><li><strong><a href="./packaging.html">封裝與發布</a></strong> —— 編譯好的外掛 DLL 是如何被發現並載入的。</li></ul><p>本手冊裡的每一個介面簽章都直接對照目前 <code>PluginSdk</code> 原始碼核實過——如果發現和文件有出入，以程式碼為準。</p>',4)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
